INSERT INTO tq_questions (subjectId, chapterId, type, difficulty, text, explanation, marks, isLegacy, legacyId, isActive) SELECT sj.id, ch.id, 'SINGLE_MCQ', 'MEDIUM', '<table> <tbody> <tr> <td> <p>If <m:r></m:r><m:omath><i>3.8 ×</i><m:ssup><m:ssuppr><m:ctrlpr></m:ctrlpr></m:ssuppr><m:e><i><m:r>10</m:r></i></m:e><m:sup></m:sup><sup><m:sup><i><m:r><sup>-</sup></m:r><m:r><sup>6</sup></m:r></i></m:sup></sup></m:ssup></m:omath> is added to <m:r></m:r><m:omath><i>4.2 ×</i><m:ssup><m:ssuppr><m:ctrlpr></m:ctrlpr></m:ssuppr><m:e><i><m:r>10</m:r></i></m:e><m:sup></m:sup></m:ssup></m:omath><sup><m:omath><m:ssup><m:sup><i><m:r><sup>-</sup></m:r><m:r><sup>5</sup></m:r></i></m:sup></m:ssup></m:omath> </sup>giving due regard to significant figures, then the result will be</p> </td> </tr> </tbody> </table>', NULL, 1, 1, 22426, 1 FROM tq_chapters ch JOIN tq_offerings o ON o.id=ch.offeringId JOIN tq_boards b ON b.id=o.boardId JOIN tq_classes c ON c.id=o.classId JOIN tq_subjects sj ON sj.id=o.subjectId WHERE b.code='CBSE' AND c.name='Class 11' AND sj.name='Physics' AND ch.name='General';
