INSERT INTO tq_questions (subjectId, chapterId, type, difficulty, text, explanation, marks, isLegacy, legacyId, isActive) SELECT sj.id, ch.id, 'SINGLE_MCQ', 'MEDIUM', '<table> <tbody> <tr> <td> <p>When a <m:r></m:r><m:omath><i>1.0 <m:r>kg</m:r></i></m:omath> mass hangs attached to a spring of length <m:r></m:r><m:omath><i>50 <m:r>cm</m:r></i></m:omath> , the spring stretches by <m:r></m:r><m:omath><i>2 <m:r>cm</m:r></i></m:omath> . The mass is pulled down until the length of the spring becomes <m:r></m:r><m:omath><i>60 <m:r>cm</m:r></i></m:omath> . What is the amount of elastic energy stored in the spring in this condition, if <m:r></m:r><m:omath><i>g<m:r>=10 </m:r><m:r>m</m:r><m:r>/</m:r></i><m:ssup><m:ssuppr><m:ctrlpr></m:ctrlpr></m:ssuppr><m:e><i><m:r>s</m:r></i></m:e><m:sup></m:sup></m:ssup></m:omath><sup><m:omath><m:ssup><m:sup><i><m:r><sup>2</sup></m:r></i></m:sup></m:ssup></m:omath></sup></p> </td> </tr> </tbody> </table>', NULL, 1, 1, 22463, 1 FROM tq_chapters ch JOIN tq_offerings o ON o.id=ch.offeringId JOIN tq_boards b ON b.id=o.boardId JOIN tq_classes c ON c.id=o.classId JOIN tq_subjects sj ON sj.id=o.subjectId WHERE b.code='CBSE' AND c.name='Class 11' AND sj.name='Physics' AND ch.name='General';
