INSERT INTO tq_questions (subjectId, chapterId, type, difficulty, text, explanation, marks, isLegacy, legacyId, isActive) SELECT sj.id, ch.id, 'SINGLE_MCQ', 'MEDIUM', '<p>A bomb of mass <m:r></m:r> <i>M</i> <img id="_x0000_i1025" src="file:///C:/Users/itzzr/AppData/Local/Temp/msohtmlclip1/01/clip_image001.png" /> at rest explodes into two fragments of masses <m:ctrlpr></m:ctrlpr> <i><m:r>m</m:r></i> <sub><i><m:r><sub>1</sub></m:r></i> </sub>and <m:ctrlpr></m:ctrlpr> <i><m:r>m</m:r></i><sub> </sub><i><m:r><sub>2</sub></m:r></i> . The total energy released in the explosion is <m:r></m:r> <i>E</i> <img id="_x0000_i1025" src="file:///C:/Users/itzzr/AppData/Local/Temp/msohtmlclip1/01/clip_image004.png" /> . If <m:ctrlpr></m:ctrlpr> <i><m:r>E</m:r></i> <sub><i><m:r><sub>1</sub></m:r></i> </sub> and <m:ctrlpr></m:ctrlpr> <i><m:r>E</m:r></i> <sub><i><m:r><sub>2</sub></m:r></i> </sub> represent the energies carried by masses <m:ctrlpr></m:ctrlpr> <i><m:r>m</m:r></i> <sub><i><m:r><sub>1</sub></m:r></i></sub> and <m:ctrlpr></m:ctrlpr> <i><m:r>m</m:r></i> <sub><i><m:r><sub>2</sub></m:r></i></sub> respectively, then which of the following is correct?</p>', NULL, 1, 1, 22466, 1 FROM tq_chapters ch JOIN tq_offerings o ON o.id=ch.offeringId JOIN tq_boards b ON b.id=o.boardId JOIN tq_classes c ON c.id=o.classId JOIN tq_subjects sj ON sj.id=o.subjectId WHERE b.code='CBSE' AND c.name='Class 11' AND sj.name='Physics' AND ch.name='General';
